import { defineConfig, lazyPlugins } from "vite-plus";

import { tanstackStart } from "@tanstack/react-start/plugin/vite";

import { nitro } from "nitro/vite";

import viteReact from "@vitejs/plugin-react";

import { imagetools } from "vite-imagetools";

import { playwright } from "vite-plus/test/browser-playwright";

import { staticSecurityHeaders } from "./src/server/security-headers";

const config = defineConfig({
  fmt: {
    // plan/ is hand-written prose; routeTree.gen.ts is generated by TanStack Router
    ignorePatterns: ["plan/**", "src/routeTree.gen.ts"],
  },
  staged: {
    "*": "vp check --fix",
  },
  lint: {
    jsPlugins: [{ name: "vite-plus", specifier: "vite-plus/oxlint-plugin" }],
    rules: { "vite-plus/prefer-vite-plus-imports": "error" },
    options: { typeAware: true, typeCheck: true },
  },
  resolve: { tsconfigPaths: true },
  // TanStack Start and Nitro are app plugins; loaded in the test runner they throw "module is not
  // defined" from React's CJS entry. So the projects don't extend this config (`extends: false`),
  // and the root plugin list is empty under Vitest (below).
  test: {
    projects: [
      {
        extends: false,
        resolve: { tsconfigPaths: true },
        test: { name: "unit", environment: "node", include: ["src/**/*.test.ts"] },
      },
      {
        extends: false,
        resolve: { tsconfigPaths: true },
        // imagetools: components import responsive images (e.g. the landing hero)
        plugins: [viteReact(), imagetools()],
        // Pre-bundle together up front: found late, lucide-react gets its own copy of React (hooks fail)
        optimizeDeps: {
          include: [
            "react",
            "react-dom",
            "react-dom/client",
            "lucide-react",
            "vitest-browser-react",
          ],
        },
        test: {
          name: "component",
          include: ["src/**/*.browser.test.tsx"],
          setupFiles: ["src/test/setup.browser.ts"],
          browser: {
            enabled: true,
            provider: playwright(),
            headless: true,
            instances: [{ browser: "chromium" }],
          },
        },
      },
    ],
  },
  plugins: lazyPlugins(() => (process.env.VITEST ? [] : appPlugins())),
});

function appPlugins() {
  return [
    tanstackStart(),
    // The Vercel preset is picked automatically when building on Vercel
    nitro({
      vercel: {
        // London, next to Neon aws-eu-west-2 (plan/engineering.md section 2)
        functions: { regions: ["lhr1"] },
        // Security headers on every response, static files included. `continue` lets the
        // asset cache route still match. The per-request CSP is set in src/start.ts.
        config: {
          version: 3,
          routes: [{ src: "/(.*)", headers: staticSecurityHeaders, continue: true }],
        },
      },
    }),
    viteReact(),
    // Responsive AVIF/WebP/JPEG sizes from `?w=…&format=…&as=picture` imports, built into /assets
    imagetools(),
  ];
}

export default config;
